cd /Users/eryk.napierala/conductor/workspaces/werk/iqaluit; cat > /tmp/shot.mjs <<'EOF'
import { chromium } from 'playwright'
const b = await chromium.launch()
for (const w of [1000, 520]) {
  const p = await b.newPage({ viewport: { width: w, height: 900 } })
  await p.addInitScript(() => localStorage.setItem('werk-view', 'flow'))
  await p.goto('http://localhost:4000/')
  await p.waitForSelector('.kill-gauge', { timeout: 10000 })
  await p.locator('.kill-gauge').screenshot({ path: `/tmp/kg-${w}.png` })
}
await b.close()
EOF
cp /tmp/shot.mjs ./.shot.mjs && bun ./.shot.mjs; rm -f ./.shot.mjs
